/**
 * Analyze an AST and extract top-level function declarations
 *
 * @param {object} ast - Abstract Syntax Tree (AST) generated by the parser
 * @returns {object[]} functions with their names, parameters and calls
 */
export function analyzeSource(ast) {
  const functions = [];

  ast.body.forEach((node) => {
    if (node.type === "FunctionDeclaration") {
      const calls = [];

      node.body.body.forEach((statement) => {
        if (
          statement.type === "ExpressionStatement" &&
          statement.expression.type === "CallExpression" &&
          statement.expression.callee.type === "Identifier"
        ) {
          calls.push(statement.expression.callee.name);
        }
      });

      functions.push({
        name: node.id.name,
        parameters: node.params.map((param) => param.name),
        calls: calls,
      });
    }
  });

  return functions;
}
